/**
 * Where each party runs (generated by `scripts/generate_partidos.py`)
 * and how parties split into national and regional.
 */
import { z } from 'astro/zod';
import rawPresence from '@eleccion/presencia.json';
import { compareText } from './format';
import { unique } from './collections';
import { geography } from './geography';
import { programs, type Program } from './programs';

const presenceSchema = z
  .object({
    comunidadPorProvincia: z.record(z.string(), z.string()),
    partidos: z.record(
      z.string(),
      z.object({
        ambito: z.enum(['estatal', 'autonomico']),
        comunidades: z.array(z.string()),
        congreso: z.array(z.string()),
        senado: z.array(z.string()),
      }),
    ),
  })
  .transform((raw) => ({
    regionByProvince: raw.comunidadPorProvincia,
    parties: Object.fromEntries(
      Object.entries(raw.partidos).map(([id, party]) => [
        id,
        {
          scope: party.ambito === 'estatal' ? ('national' as const) : ('regional' as const),
          /** Regions where the party runs, from the most to the fewest provinces. */
          regions: party.comunidades,
          /** INE codes of the provinces with a list for the Congress. */
          congress: party.congreso,
          /** INE codes of the provinces with a list for the Senate. */
          senate: party.senado,
        },
      ]),
    ),
  }));

export type Presence = (typeof presenceData.parties)[string];

const presenceData = presenceSchema.parse(rawPresence);

export const provinces = geography.provinces.map(({ code, name }) => ({
  code,
  name,
  region: presenceData.regionByProvince[code],
}));
export const provinceByCode = Object.fromEntries(provinces.map((province) => [province.code, province]));
export const provinceRegions = unique(provinces.map((province) => province.region)).sort(compareText);

export function presenceOf(program: Program): Presence {
  return (
    presenceData.parties[program.id] ?? {
      scope: program.region ? 'regional' : 'national',
      regions: program.region ? [program.region] : [],
      congress: [],
      senate: [],
    }
  );
}

/** Province codes where the party runs a list (Congress or Senate). */
export const provincesOf = (program: Program) => {
  const { congress, senate } = presenceOf(program);
  return unique([...congress, ...senate]).sort();
};

export const nationalPrograms = programs.filter((program) => presenceOf(program).scope === 'national');
export const regionalPrograms = programs.filter((program) => presenceOf(program).scope === 'regional');

/** Regions with at least one regional party, in alphabetical order. */
export const regionalRegions = unique(regionalPrograms.flatMap((program) => presenceOf(program).regions)).sort(compareText);

/** Regional parties of one region. A party shows in every region where it runs. */
export const regionalProgramsIn = (region: string) =>
  regionalPrograms.filter((program) => presenceOf(program).regions.includes(region));
